import 'package:flutter/material.dart';
import 'package:flutter_toasty/src/models/enums.dart';
import 'package:flutter_toasty/src/models/toasty_options.dart';

class ToastItem {
  ToastItem({
    required this.id,
    required this.message,
    this.title,
    required this.options,
    this.child,
    this.onClick,
    this.onClose,
    this.position = ToastPosition.bottomCenter,
    this.type = ToastType.info,
  });

  /// Unique identifier for this toast, used for dismissal and management. Generated by the manager when the toast is shown.
  final String id;

  /// The main message to display in the toast. This is required and should be a concise string.
  final String message;

  /// The type of the toast, which determines its default styling and icon.
  /// Default to type
  final String? title;

  /// An optional widget replace message text.
  /// If provided, this widget will be displayed instead of the default text and icon.
  ///  This allows for fully custom toast content while still using the manager's show/dismiss functionality.
  final Widget? child;

  /// onClick callback when the toast is tapped.
  /// This can be used to perform an action when the user interacts with the toast,
  ///  such as navigating to a different screen or showing more details.
  final VoidCallback? onClick;

  /// onClose callback when the toast is dismissed, either by auto-close or user action.
  /// This can be used to perform cleanup or trigger side effects when the toast is removed.
  final VoidCallback? onClose;

  /// The position of the toast on the screen, determined by the manager's configuration.
  final ToastPosition position;

  /// The type of the toast, which determines its default styling and icon.
  final ToastType type;

  /// The options for this toast,
  final ToastItemOptions options;
}
